// wf.match.search > "Plan"
// Input: {jurisdiction, q, max_rent_minor, currency, budget_period, lat, lng, place, radius_m,
// limit} and settings. A text query is embedded (bge-m3, the model chosen in phase 2) unless empty.
const s = $('Start').first().json;
const cfg = $input.first().json.cfg || {};
const q = typeof s.q === 'string' ? s.q.trim() : '';
const p = { jurisdiction: s.jurisdiction, q_text: q || null, max_rent_minor: s.max_rent_minor ?? null, currency: s.currency || null,
  budget_period: s.budget_period || null, lat: s.lat ?? null, lng: s.lng ?? null, place: s.place || null,
  radius_m: s.radius_m ?? null, limit: s.limit ?? null };
return [{ json: { t0: Date.now(), p, embed: !!q, url: `${String(cfg['ollama.base_url'] || '').replace(/\/+$/, '')}/api/embed`,
  body: { model: cfg['ollama.embed_model'] || 'bge-m3', input: [q], truncate: true, keep_alive: cfg['llm.keep_alive'] || '10m' } } }];

// wf.match.search > "Query vector"
// Embedding answer -> search parameters. If the embedding fails the search still runs on
// its lexical side, with the warning code embedding_unavailable (spec 8.8: degrade, not fail).
const plan = $('Plan').first().json;
const res = $input.first().json;
let vec = null, warning = null;
const t1 = Date.now();
try {
  let b = res.body !== undefined ? res.body : res;
  if (typeof b === 'string') b = JSON.parse(b);
  const v = b && b.embeddings && b.embeddings[0];
  if (Array.isArray(v) && v.length === 1024) vec = `[${v.join(',')}]`;
  else warning = 'embedding_unavailable';
} catch (e) { warning = 'embedding_unavailable'; }
return [{ json: { params: [JSON.stringify({ ...plan.p, q_vec: vec })], embed_ms: t1 - plan.t0, warning } }];

// wf.match.search > "No text": filters-only search, no embedding.
const plan = $input.first().json;
return [{ json: { params: [JSON.stringify(plan.p)], embed_ms: 0, warning: null } }];

// wf.match.search > "Result"
// app.search_public answer plus timings: embed_ms (query embedding), db_ms (inside the
// database), total_ms (whole sub-workflow). Spec 2.6: search p95 excluding explanations.
const plan = $('Plan').first().json;
const prev = $('Search input').first().json;
const r = $input.first().json.r || {};
if (r.error) return [{ json: { ok: false, error_code: r.error } }];
const warnings = [...(r.warnings || [])];
if (prev.warning) warnings.push(prev.warning);
return [{ json: { ok: true, mode: r.mode, results: r.results || [], count: r.count || 0, applied: r.applied, warnings,
  timings: { embed_ms: prev.embed_ms, db_ms: r.db_ms, total_ms: Date.now() - plan.t0 } } }];
